// Generated by scripts/generateFirstUnsupportedAnnotationCharacter.ts.
import coverage from '@contracts/annotationFontCoverage.json';

// What the general face maps; each script face claims its unicodeRange.
const ranges: ReadonlyArray<readonly number[]> = coverage.ranges;

const invisible = (code: number) => code === 0x09 || code === 0x0a || code === 0x0d || code === 0xad
    || code === 0x61c || (code >= 0x200b && code <= 0x200f)
    || (code >= 0x2028 && code <= 0x202e) || (code >= 0x2060 && code <= 0x206f)
    || (code >= 0xfe00 && code <= 0xfe0f) || code === 0xfeff;

function within(list: ReadonlyArray<readonly number[]>, code: number) {
    let low = 0;
    let high = list.length;
    while (low < high) {
        const middle = Math.floor((low + high) / 2);
        const range = list[middle]!;
        if (code < range[0]!) high = middle;
        else if (code > range[1]!) low = middle + 1;
        else return true;
    }
    return false;
}

// A script face claims its range; the general face, last, claims what it maps and what draws nothing.
const claims = (face: number, code: number) => {
    const font = coverage.fonts[face]!;
    return 'unicodeRange' in font ? within(font.unicodeRange, code) : invisible(code) || within(ranges, code);
};

export function firstUnsupportedAnnotationCharacter(text: string): string | undefined {
    for (const {segment} of new Intl.Segmenter(undefined, {granularity: 'grapheme'}).segment(text)) {
        const codes = [...segment].map(character => character.codePointAt(0)!);
        const control = codes.find(code => (code < 0x20 || (code >= 0x7f && code <= 0x9f)) && !invisible(code));
        const drawn = coverage.fonts.some((_, face) => codes.every(code => claims(face, code)));
        const refused = control ?? (drawn ? undefined : codes.find(code => !claims(coverage.fonts.length - 1, code)));
        if (refused !== undefined) {
            return String.fromCodePoint(refused);
        }
    }
    return undefined;
}
